def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Final round: no shadow of the future, take the shot if it helps.
    if n >= 100:
        return 'D'

    # Extract opponent moves compactly.
    opp = [b for a, b in history]
    my = [a for a, b in history]

    # ---- Early game: establish cooperation, but quickly punish defection ----
    if n < 4:
        if n == 0:
            return 'C'
        # If opponent opened with defection, retaliate immediately.
        if opp[-1] == 'D':
            return 'D'
        return 'C'

    # Recent windows
    recent10 = opp[-10:]
    recent5 = opp[-5:]
    d10 = sum(1 for x in recent10 if x == 'D')
    d5 = sum(1 for x in recent5 if x == 'D')

    # Total opponent cooperation rate
    opp_c = sum(1 for x in opp if x == 'C')
    opp_d = n - opp_c

    # ---- Recognize unconditional cooperators / mostly-cooperative bots ----
    # The parent loses against TFT probes because it traps itself in DD cycles.
    # Against very cooperative opponents, maintain cooperation and exploit rarely.
    if n >= 8:
        if d10 == 0:
            # Opponent hasn't defected in 10 rounds: cooperate, but probe once near end.
            if n >= 96:
                return 'D'
            if n == 55 or n == 75:
                return 'D'
            return 'C'
        if d10 <= 1 and opp_d * 4 <= n:
            # Very cooperative: cooperate mostly, small periodic tests.
            if n >= 96:
                return 'D'
            if n % 13 == 0:
                return 'D'
            return 'C'

    # ---- Handle opponents who exploit us after we cooperated ----
    # If last round was CD (our C, their D), retaliate, but be willing to
    # re-establish cooperation against TFT-like players.
    if opp[-1] == 'D':
        # If we defected too (DD), try to break defection spiral.
        if my[-1] == 'D':
            # Count consecutive DD rounds.
            cons_dd = 0
            for i in range(n - 1, -1, -1):
                if my[i] == 'D' and opp[i] == 'D':
                    cons_dd += 1
                else:
                    break
            if cons_dd >= 3:
                # Opponent may be TFT; occasional unilateral C can restart cooperation.
                if rng.random() < 0.35:
                    return 'C'
                return 'D'
            if cons_dd >= 1 and rng.random() < 0.15:
                return 'C'
            return 'D'
        else:
            # We cooperated, opponent defected: punish.
            # But against TFT-like opponents, a single D is enough to send the message;
            # then return to C soon to avoid a long DD cycle.
            if n >= 96:
                return 'D'
            # If opponent has been very cooperative historically (likely TFT that
            # just retaliated for our earlier offense), forgive after one round.
            if opp_d * 3 <= n and d5 <= 2:
                return 'C'
            # Hard punish against persistent defectors.
            if d5 >= 3 or opp_d * 2 >= n:
                return 'D'
            # Moderate punishment.
            if rng.random() < 0.65:
                return 'D'
            return 'C'

    # Opponent just cooperated.
    # If we defected last round, return to cooperation to avoid feuds.
    if my[-1] == 'D':
        # But if opponent is a pushover (never retaliates), keep exploiting.
        retaliations = 0
        my_d_prev = 0
        for i in range(1, n):
            if my[i - 1] == 'D':
                my_d_prev += 1
                if opp[i] == 'D':
                    retaliations += 1
        if my_d_prev >= 3 and retaliations * 3 < my_d_prev:
            # Opponent rarely retaliates: exploit more.
            if n < 96:
                return 'D'
        return 'C'

    # Both cooperated last round.
    # Against mostly-cooperative opponents, mostly cooperate.
    if opp_d * 4 <= n:
        if n >= 96:
            return 'D'
        if n % 17 == 0 and n > 20:
            return 'D'
        return 'C'

    # Against mixed opponents, use a lenient tit-for-tat.
    # Check for TFT-like behavior: does opponent copy our previous action?
    if n >= 6:
        tft_matches = 0
        for i in range(1, n):
            if opp[i] == my[i - 1]:
                tft_matches += 1
        if tft_matches * 4 >= (n - 1) * 3:
            # Likely TFT: cooperate to keep mutual cooperation.
            if n >= 96 and d5 >= 1:
                return 'D'
            return 'C'

    # Moderate cooperation.
    if d5 >= 3:
        return 'D'
    if d5 >= 1:
        # Recent defections but opponent just cooperated: cautious cooperation.
        if rng.random() < 0.75:
            return 'C'
        return 'D'

    return 'C'
